// rustc debug_unicode.rs -o /tmp/debug_unicode && /tmp/debug_unicode > lib/src/debug_unicode.dart
// Capture Rust str's Debug character policy independently of the Dart runtime's Unicode version.
fn main() {
    println!(
        "// Generated by test/reference/debug_unicode.rs from Rust char::escape_debug.\npart of '../fleece.dart';\n\nconst _debugEscapeBoundaries = <int>["
    );
    let mut escaped = false;
    let mut col = 0;
    for n in 0..=0x110000 {
        let next =
            char::from_u32(n).is_some_and(|c| c.escape_debug().to_string().starts_with("\\u{"));
        if escaped != next {
            print!("0x{n:x}, ");
            col += 1;
            if col % 9 == 0 {
                println!();
            }
            escaped = next;
        }
    }
    println!("\n];");
}
